    def test_verify(
        self,
        name: str,
        pk_bytes: bytes,
        msg: bytes,
        ctx: bytes,
        sig: bytes,
        expected: bool,
    ):
        try:
            pk = VerificationKey.from_bytes(pk_bytes)
        except ValueError:
            self.assertFalse(expected)
        else:
            actual = pk.verify(sig, msg, ctx)
            self.assertIs(actual, expected)
